import java.util.Scanner;

public class Main {
    static long[] A = new long[20];

    static long dfs(int ind, long n) {
        if (ind == 0)
            return n == 0 ? 0 : (long) 1e8;
        if (n < 0)
            n = -n;
        long m = n / A[ind];
        return Math.min(dfs(ind - 1, n - m * A[ind]) + m * ind,
                        dfs(ind - 1, n - (m + 1) * A[ind]) + (m + 1) * ind);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        A[0] = 1;
        for (int i = 1; i <= 16; ++i) {
            A[i] = A[i - 1] * 10 + 1;
        }
        System.out.println(dfs(16, n));
        sc.close();
    }
}
